class Solution {
public:
    long long minimumRemoval(vector<int>& beans) {
        sort(beans.begin(), beans.end());
        int n = beans.size();
        long long total = accumulate(beans.begin(), beans.end(), 0LL);
        long long best = LLONG_MAX;
        for (int i = 0; i < n; i++)
            best = min(best, total - (long long)beans[i] * (n - i));
        return best;
    }
};

