        int n = beans.length;
        long total = 0;
        for (int b : beans) total += b;
        long best = Long.MAX_VALUE;
        for (int i = 0; i < n; i++)
            best = Math.min(best, total - (long) beans[i] * (n - i));
        return best;
    }
}

