class Solution:
    def minimumRemoval(self, beans):
        M = max(beans)
        cnt = [0] * (M + 1)
        for b in beans:
            cnt[b] += 1
        total = sum(beans)
        best = float('inf')
        sc = 0
        for v in range(M, 0, -1):
            sc += cnt[v]
            best = min(best, total - v * sc)
        return best

