var minimumRemoval = function(beans) {
    const M = Math.max(...beans);
    const cnt = new Array(M + 1).fill(0);
    for (const b of beans) cnt[b]++;
    const total = beans.reduce((a, b) => a + b, 0);
    let best = Infinity, sc = 0;
    for (let v = M; v >= 1; v--) {
        sc += cnt[v];
        best = Math.min(best, total - v * sc);
    }
    return best;
};
